/**
 * Realistic semester fixture: 3 semesters (3, 5, 7) x 5 divisions, 8 subjects, 12 faculty,
 * 15 classrooms + 4 lab rooms, lab batches A1-A3 per division.
 *
 *   buildSemesterState({divisions: 15}) -> readiness/sessionSync `state`
 *   FIXTURE_FACULTY / FIXTURE_SUBJECTS / FIXTURE_ROOMS / buildDivisionRows() / buildOfferingRows()
 *     -> the same data as flat CSV-style row objects (see faculty.csv, subjects.csv, divisions.csv,
 *        offerings.csv next to this file, generated by generateCsv.js from these rows).
 *
 * The CSV `home_room` column is intentionally blank (rooms live in the Vyas DB, not in the fixture);
 * pass {homeRooms:true} to buildDivisionRows() to get "Main Building / C101"-style values.
 * Lab batch names are `<letter>1..3` (A1, A2, A3 for division CSE-A; B1.. for CSE-B ...).
 */

export const SEMESTERS = [3, 5, 7];
export const TERM_WEEKS = 15;
const LETTERS = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H'];

export const FIXTURE_FACULTY = [
  ['Sharma', 'Anil Sharma'], ['Patil', 'Sunita Patil'], ['Kulkarni', 'Rahul Kulkarni'],
  ['Deshmukh', 'Meera Deshmukh'], ['Joshi', 'Vikas Joshi'], ['Kale', 'Pooja Kale'],
  ['Bhosale', 'Sanjay Bhosale'], ['More', 'Neha More'], ['Pawar', 'Amit Pawar'],
  ['Gokhale', 'Anjali Gokhale'], ['Naik', 'Rohan Naik'], ['Rane', 'Kavita Rane'],
].map(([short_code, full_name], i) => ({
  short_code,
  full_name,
  email: `${short_code.toLowerCase()}@mitwpu.edu.in`,
  department: 'Computer Science',
  max_per_day: 6,
  max_per_week: 24,
  linked: i % 2 === 0, // half of them have a Vyas login profile
}));

export const FIXTURE_SUBJECTS = [
  { code: 'DS', name: 'Data Structures', kind: 'theory', weekly_count: 4, duration_min: 60 },
  { code: 'OS', name: 'Operating Systems', kind: 'theory', weekly_count: 3, duration_min: 60 },
  { code: 'Maths', name: 'Engineering Mathematics', kind: 'theory', weekly_count: 4, duration_min: 60 },
  { code: 'CN', name: 'Computer Networks', kind: 'theory', weekly_count: 3, duration_min: 60 },
  { code: 'DBMS', name: 'Database Management Systems', kind: 'theory', weekly_count: 3, duration_min: 60 },
  { code: 'TC', name: 'Technical Communication', kind: 'theory', weekly_count: 2, duration_min: 60 },
  { code: 'DS Lab', name: 'Data Structures Lab', kind: 'lab', weekly_count: 1, duration_min: 120 },
  { code: 'DBMS Lab', name: 'DBMS Lab', kind: 'lab', weekly_count: 1, duration_min: 120 },
].map((s) => ({ ...s, semester_total: s.weekly_count * TERM_WEEKS, allow_second_lab: false }));

/** Subjects taken in each semester. */
export const SEMESTER_SUBJECTS = {
  3: ['DS', 'OS', 'Maths', 'TC', 'DS Lab'],
  5: ['DBMS', 'CN', 'OS', 'TC', 'DBMS Lab'],
  7: ['CN', 'DBMS', 'Maths', 'DS Lab', 'DBMS Lab'],
};

export const FIXTURE_BUILDING = 'Main Building';
export const FIXTURE_ROOMS = [
  ...Array.from({ length: 15 }, (_, i) => ({ name: `C${101 + i}`, is_lab: false, capacity: 70 })),
  ...Array.from({ length: 4 }, (_, i) => ({ name: `Lab ${i + 1}`, is_lab: true, capacity: i === 3 ? null : 30 })),
].map((r) => ({ ...r, building_name: FIXTURE_BUILDING }));

const DIV_STUDENTS = 60;
const BATCH_NAMES = (letter) => [1, 2, 3].map((n) => `${letter}${n}`);

/** The divisions of the fixture: [{index, semester, letter, name}] (semester-major order). */
export function fixtureDivisions(count = 15) {
  const perSem = Math.max(1, Math.ceil(count / SEMESTERS.length));
  const out = [];
  for (let i = 0; i < count; i++) {
    const semester = SEMESTERS[Math.min(SEMESTERS.length - 1, Math.floor(i / perSem))];
    const letter = LETTERS[i % perSem % LETTERS.length];
    out.push({ index: i, semester, letter, name: `CSE-${letter}` });
  }
  return out;
}

/**
 * Deterministic least-loaded assignment: faculty short code per (division index, subject slot, batch index),
 * balanced across the 12 faculty. Lab batches of one offering get different faculty.
 */
const assignmentCache = new Map();
function facultyForCount(count) {
  if (assignmentCache.has(count)) return assignmentCache.get(count);
  const load = FIXTURE_FACULTY.map(() => 0);
  const map = new Map();
  const pick = (weight, avoid) => {
    let best = -1;
    FIXTURE_FACULTY.forEach((_, i) => {
      if (avoid.has(i)) return;
      if (best < 0 || load[i] < load[best]) best = i;
    });
    load[best] += weight;
    avoid.add(best);
    return FIXTURE_FACULTY[best].short_code;
  };
  for (const d of fixtureDivisions(count)) {
    SEMESTER_SUBJECTS[d.semester].forEach((code, si) => {
      const subject = FIXTURE_SUBJECTS.find((s) => s.code === code);
      const used = new Set();
      const batches = subject.kind === 'lab' ? 3 : 1;
      for (let bi = 0; bi < batches; bi++) map.set(`${d.index}|${si}|${bi}`, pick(subject.weekly_count, used));
    });
  }
  const lookup = (divIndex, subjectIndex, batchIndex = 0) => map.get(`${divIndex}|${subjectIndex}|${batchIndex}`);
  assignmentCache.set(count, lookup);
  return lookup;
}

/** Flat offerings rows (CSV shape). Lab offerings get one row per batch with a different faculty member. */
export function buildOfferingRows(count = 15) {
  const rows = [];
  for (const d of fixtureDivisions(count)) {
    SEMESTER_SUBJECTS[d.semester].forEach((code, si) => {
      const subject = FIXTURE_SUBJECTS.find((s) => s.code === code);
      if (subject.kind === 'lab') {
        BATCH_NAMES(d.letter).forEach((batch, bi) => {
          rows.push({ semester: d.semester, division: d.name, subject_code: code, faculty_codes: facultyForCount(count)(d.index, si, bi), batch, weekly_count: '', role: '' });
        });
      } else {
        rows.push({ semester: d.semester, division: d.name, subject_code: code, faculty_codes: facultyForCount(count)(d.index, si), batch: '', weekly_count: '', role: '' });
      }
    });
  }
  return rows;
}

/** Flat divisions rows (CSV shape), one per batch. */
export function buildDivisionRows(count = 15, { homeRooms = false } = {}) {
  const rows = [];
  for (const d of fixtureDivisions(count)) {
    const room = FIXTURE_ROOMS[d.index % 15];
    BATCH_NAMES(d.letter).forEach((batch) => {
      rows.push({
        semester: d.semester,
        division: d.name,
        student_count: DIV_STUDENTS,
        home_room: homeRooms ? `${room.building_name} / ${room.name}` : '',
        batch,
        batch_size: DIV_STUDENTS / 3,
      });
    });
  }
  return rows;
}

export function buildSemesterState({ divisions = 15 } = {}) {
  const count = divisions;
  const term = {
    id: 'term-fixture',
    academic_year: '2026-27',
    half: 'odd',
    branch: 'CSE',
    start_date: '2026-07-27',
    end_date: '2026-11-08',
    working_days: [0, 1, 2, 3, 4],
    day_start_min: 510,
    day_end_min: 1065,
    grid_minutes: 15,
    theory_minutes: 60,
    lab_minutes: 120,
    breaks: [
      { start_min: 630, end_min: 645, label: 'Short break 1' },
      { start_min: 765, end_min: 810, label: 'Lunch' },
      { start_min: 930, end_min: 945, label: 'Short break 2' },
    ],
  };
  const rooms = FIXTURE_ROOMS.map((r, i) => ({
    id: `tr-${i + 1}`,
    room_id: `room-${i + 1}`,
    is_lab: r.is_lab,
    name: r.name,
    building_name: r.building_name,
    capacity: r.capacity,
  }));
  const faculty = FIXTURE_FACULTY.map((f, i) => ({
    id: `fac-${f.short_code}`,
    short_code: f.short_code,
    full_name: f.full_name,
    email: f.email,
    profile_id: f.linked ? `profile-${i + 1}` : null,
    max_per_day: f.max_per_day,
    max_per_week: f.max_per_week,
  }));
  const subjects = FIXTURE_SUBJECTS.map((s) => ({ id: `sub-${s.code}`, ...s }));
  const byFaculty = (code) => faculty.find((f) => f.short_code === code).id;

  const divs = [];
  const offerings = [];
  for (const d of fixtureDivisions(divisions)) {
    const id = `div-${d.semester}-${d.letter}`;
    divs.push({
      id,
      semester: d.semester,
      name: d.name,
      student_count: DIV_STUDENTS,
      home_room_id: rooms[d.index % 15].room_id,
      batches: [
        { id: `${id}-ALL`, name: 'ALL', student_count: DIV_STUDENTS, is_whole: true },
        ...BATCH_NAMES(d.letter).map((n) => ({ id: `${id}-${n}`, name: n, student_count: DIV_STUDENTS / 3, is_whole: false })),
      ],
    });
    SEMESTER_SUBJECTS[d.semester].forEach((code, si) => {
      const subject = subjects.find((s) => s.code === code);
      const lab = subject.kind === 'lab';
      offerings.push({
        id: `off-${id}-${code}`,
        division_id: id,
        subject_id: subject.id,
        weekly_count: null,
        per_batch: lab,
        faculty: lab
          ? BATCH_NAMES(d.letter).map((n, bi) => ({ batch_id: `${id}-${n}`, faculty_id: byFaculty(facultyForCount(count)(d.index, si, bi)), role: 'lead' }))
          : [{ batch_id: null, faculty_id: byFaculty(facultyForCount(count)(d.index, si)), role: 'lead' }],
      });
    });
  }
  return { term, rooms, faculty, subjects, divisions: divs, offerings };
}
